package com.oracle.banking.branch;
import com.oracle.banking.branch.entity.Branch;import com.oracle.banking.branch.repository.BranchRepository;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import java.util.*;
@SpringBootApplication public class BranchServiceApplication{public static void main(String[]a){SpringApplication.run(BranchServiceApplication.class,a);}@Bean CommandLineRunner initialBranches(BranchRepository r){return a->{if(r.count()==0)r.saveAll(List.of(new Branch(UUID.randomUUID().toString(),"Bengaluru Main","ORCL0000001","Bengaluru","Karnataka"),new Branch(UUID.randomUUID().toString(),"Mumbai Fort","ORCL0000002","Mumbai","Maharashtra"),new Branch(UUID.randomUUID().toString(),"Chennai Central","ORCL0000003","Chennai","Tamil Nadu")));};}}
